<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $user = $args['user']; ?>
<?php $submitted = sanitize_key( $_GET['submitted'] ?? '' ); if ( in_array( $submitted, array( 'analyst', 'situation' ), true ) && 'pending' === Revayat_Companion_Member_Applications::state( Revayat_Companion_Member_Applications::latest( $user->ID, $submitted ) ) ) : ?><p class="rv-member-notice" role="status">درخواست شما ثبت شد و در انتظار بررسی است. ارسال دوباره لازم نیست؛ نتیجه و توضیحات بررسی در همین بخش و اعلان‌ها نمایش داده می‌شود.</p><?php endif; ?>
<div class="rv-member-grid"><?php foreach ( array( 'analyst' => array( 'تحلیلگر شوید', 'یادداشت‌های تخصصی شما پس از بررسی تحریریه منتشر می‌شوند. حوزه فعالیت و معرفی حرفه‌ای خود را ارسال کنید.', 'analyst-request', 'pen-nib' ), 'situation' => array( 'دسترسی اتاق وضعیت', 'برای مطالعه گزارش‌های ویژه، درخواست دسترسی و مدارک هویتی خود را به‌صورت خصوصی ارسال کنید.', 'situation-access', 'shield-check' ) ) as $type => $item ) : $application = Revayat_Companion_Member_Applications::latest( $user->ID, $type ); $state = Revayat_Companion_Member_Applications::state( $application ); ?><section class="rv-member-card" data-application-type="<?php echo esc_attr( $type ); ?>"><i class="ph ph-<?php echo esc_attr( $item[3] ); ?> rv-member-feature-icon"></i><h2><?php echo esc_html( $item[0] ); ?></h2><p><?php echo esc_html( $item[1] ); ?></p><span class="rv-member-badge" data-application-state><?php echo esc_html( Revayat_Companion_Member_Applications::labels()[ $state ] ); ?></span><a data-application-link class="rv-member-secondary" href="<?php echo esc_url( home_url( '/dashboard/?view=' . $item[2] ) ); ?>"><?php echo 'none' === $state ? 'شرایط و ثبت درخواست' : 'مشاهده و پیگیری'; ?><i class="ph ph-arrow-left"></i></a></section><?php endforeach; ?></div>
